// tui/colors_golden_test.go — oklab.go/colors.go/terminal_colors.go against
// golden output generated by running pi's TypeScript sources directly
// (node v24, /Users/lee/Projects/pi/packages/tui/src/{oklab,colors,
// terminal-colors}.ts at the S10-3 baseline, v0.99.1). Regenerate with the
// script in docs/handoffs/S10-3.md. This is the S10-3 equivalent of the
// per-field catalog comparison: the color math must agree with pi to the
// exact byte after the 0-255 rounding.
package tui

import (
	"encoding/json"
	"fmt"
	"math"
	"os"
	"testing"
)

type goldenRgb struct {
	R int `json:"r"`
	G int `json:"g"`
	B int `json:"b"`
}

func (c goldenRgb) value() RgbColor { return RgbColor{R: c.R, G: c.G, B: c.B} }

type goldenOkhsl struct {
	H float64 `json:"h"`
	S float64 `json:"s"`
	L float64 `json:"l"`
}

type goldenColor struct {
	Kind  string   `json:"kind"`
	Index int      `json:"index,omitempty"`
	R     int      `json:"r,omitempty"`
	G     int      `json:"g,omitempty"`
	B     int      `json:"b,omitempty"`
	L     *float64 `json:"l,omitempty"`
	C     *float64 `json:"c,omitempty"`
	H     *float64 `json:"h,omitempty"`
}

type goldenOklch struct {
	L float64 `json:"l"`
	C float64 `json:"c"`
	H float64 `json:"h"`
}

func loadColorsGolden(t *testing.T) map[string]json.RawMessage {
	t.Helper()
	data, err := os.ReadFile("testdata/colors_golden.json")
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	var out map[string]json.RawMessage
	if err := json.Unmarshal(data, &out); err != nil {
		t.Fatalf("parse golden: %v", err)
	}
	return out
}

func closeEnough(a, b float64) bool {
	return math.Abs(a-b) <= 1e-9
}

func assertOklch(t *testing.T, ctx string, got OklchChannels, want goldenOklch) {
	t.Helper()
	// Hue is undefined for achromatic colors: both implementations see
	// cbrt/atan2 float noise at C ~ 1e-16, so compare hue only above the
	// 1e-7 achromatic threshold mixColors uses.
	hueMatch := got.C < 1e-7 && want.C < 1e-7 || closeEnough(got.H, want.H)
	if !closeEnough(got.L, want.L) || !closeEnough(got.C, want.C) || !hueMatch {
		t.Errorf("%s: oklch = %+v, want %+v", ctx, got, want)
	}
}

func TestColorsGoldenOkhslToRgb(t *testing.T) {
	var entries []([]any)
	loadGoldenSection(t, "okhslToRgb", &entries)
	for _, e := range entries {
		h, s, l := e[0].(float64), e[1].(float64), e[2].(float64)
		want := decodeGoldenRgb(t, e[3])
		got := OkhslToRgb(h, s, l)
		if got != want.value() {
			t.Errorf("OkhslToRgb(%v, %v, %v) = %+v, want %+v", h, s, l, got, want.value())
		}
	}
}

func TestColorsGoldenRgbToOkhslOklab(t *testing.T) {
	var entries []([]any)
	loadGoldenSection(t, "rgbToOkhsl", &entries)
	for _, e := range entries {
		rgb := RgbColor{R: int(e[0].(float64)), G: int(e[1].(float64)), B: int(e[2].(float64))}
		want := decodeGoldenOkhsl(t, e[3])
		got := RgbToOkhsl(rgb)
		if !closeEnough(got.H, want.H) || !closeEnough(got.S, want.S) || !closeEnough(got.L, want.L) {
			t.Errorf("RgbToOkhsl(%+v) = %+v, want %+v", rgb, got, want)
		}
	}
	var oklabEntries []([]any)
	loadGoldenSection(t, "rgbToOklab", &oklabEntries)
	for _, e := range oklabEntries {
		rgb := RgbColor{R: int(e[0].(float64)), G: int(e[1].(float64)), B: int(e[2].(float64))}
		want := decodeGoldenTriple(t, e[3])
		got := RgbToOklab(rgb)
		for i, name := range []string{"L", "a", "b"} {
			if !closeEnough(got[i], want[i]) {
				t.Errorf("RgbToOklab(%+v)[%s] = %v, want %v", rgb, name, got[i], want[i])
			}
		}
	}
}

func TestColorsGoldenLightness(t *testing.T) {
	var entries []([]any)
	loadGoldenSection(t, "oklabLightness", &entries)
	for _, e := range entries {
		x := e[0].(float64)
		want := e[1].(float64)
		if got := OklabToOkhslLightness(x); !closeEnough(got, want) {
			t.Errorf("OklabToOkhslLightness(%v) = %v, want %v", x, got, want)
		}
	}
}

func TestColorsGoldenParse(t *testing.T) {
	var parsed []([]any)
	loadGoldenSection(t, "parse", &parsed)
	var hexes []string
	loadGoldenSection(t, "toHex", &hexes)
	var oklchs []goldenOklch
	loadGoldenSection(t, "toOklch", &oklchs)
	var okhsls []goldenOkhsl
	loadGoldenSection(t, "toOkhsl", &okhsls)
	var rgbs []goldenRgb
	loadGoldenSection(t, "toRgb", &rgbs)

	if len(parsed) != len(hexes) || len(parsed) != len(oklchs) || len(parsed) != len(okhsls) || len(parsed) != len(rgbs) {
		t.Fatalf("golden section length mismatch: parse=%d hex=%d oklch=%d okhsl=%d rgb=%d",
			len(parsed), len(hexes), len(oklchs), len(okhsls), len(rgbs))
	}
	for i, entry := range parsed {
		value := entry[0]
		got, err := ParseColor(value)
		if err != nil {
			t.Fatalf("ParseColor(%v): %v", value, err)
		}
		if hex := ColorToHex(got); hex != hexes[i] {
			t.Errorf("ParseColor(%v) hex = %s, want %s", value, hex, hexes[i])
		}
		assertOklch(t, fmt.Sprintf("ParseColor(%v)", value), ColorToOklch(got), oklchs[i])
		gotOkhsl := ColorToOkhsl(got)
		if !closeEnough(gotOkhsl.H, okhsls[i].H) || !closeEnough(gotOkhsl.S, okhsls[i].S) || !closeEnough(gotOkhsl.L, okhsls[i].L) {
			t.Errorf("ParseColor(%v) okhsl = %+v, want %+v", value, gotOkhsl, okhsls[i])
		}
		if gotRgb := ColorToRgb(got); gotRgb != rgbs[i].value() {
			t.Errorf("ParseColor(%v) rgb = %+v, want %+v", value, gotRgb, rgbs[i].value())
		}
	}
}

func TestColorsGoldenMix(t *testing.T) {
	red, err := ParseColor("#ff0000")
	if err != nil {
		t.Fatal(err)
	}
	blue, err := ParseColor("#0000ff")
	if err != nil {
		t.Fatal(err)
	}
	gray, err := ParseColor("#808080")
	if err != nil {
		t.Fatal(err)
	}
	var entries []([]any)
	loadGoldenSection(t, "mix", &entries)
	i := 0
	for _, e := range entries {
		amount, ok := e[0].(float64)
		if !ok {
			// The gray entry: ['gray', oklch-of-mix]
			got, err := MixColors(gray, blue, 0.5, "")
			if err != nil {
				t.Fatal(err)
			}
			want := decodeGoldenOklch(t, e[1])
			assertOklch(t, "mix gray", ColorToOklch(got), want)
			continue
		}
		_ = amount
		hexOklch := decodeGoldenHexPair(t, e[1])
		hexSrgb := decodeGoldenHexPair(t, e[2])
		wantOklch := decodeGoldenOklch(t, e[3])

		gotOklch, err := MixColors(red, blue, e[0].(float64), "")
		if err != nil {
			t.Fatal(err)
		}
		if hex := ColorToHex(gotOklch); hex != hexOklch {
			t.Errorf("mix oklch amount=%v: %s, want %s", e[0], hex, hexOklch)
		}
		assertOklch(t, fmt.Sprintf("mix oklch amount=%v", e[0]), ColorToOklch(gotOklch), wantOklch)
		gotSrgb, err := MixColors(red, blue, e[0].(float64), "srgb")
		if err != nil {
			t.Fatal(err)
		}
		if hex := ColorToHex(gotSrgb); hex != hexSrgb {
			t.Errorf("mix srgb amount=%v: %s, want %s", e[0], hex, hexSrgb)
		}
		i++
	}
	_ = i
}

func TestColorsGoldenAnsi(t *testing.T) {
	var entries []([]any)
	loadGoldenSection(t, "ansi256", &entries)
	for _, e := range entries {
		triple := decodeGoldenTriple(t, e[0])
		color, err := NewRgbColor(int(triple[0]), int(triple[1]), int(triple[2]))
		if err != nil {
			t.Fatal(err)
		}
		if got := ForegroundAnsi(color, ColorMode256color); got != e[1].(string) {
			t.Errorf("ForegroundAnsi(%+v, 256color) = %q, want %q", color, got, e[1].(string))
		}
		if got := ForegroundAnsi(color, ColorModeTruecolorN); got != e[2].(string) {
			t.Errorf("ForegroundAnsi(%+v, truecolor) = %q, want %q", color, got, e[2].(string))
		}
	}
}

func TestColorsGoldenStyle(t *testing.T) {
	red, err := ParseColor("#ff0000")
	if err != nil {
		t.Fatal(err)
	}
	blue, err := ParseColor("#0000ff")
	if err != nil {
		t.Fatal(err)
	}
	var entries []([]any)
	loadGoldenSection(t, "style", &entries)
	for i, e := range entries {
		attrs := decodeGoldenAttrs(t, e[0])
		got := StyleText("x", TextStyle{Fg: &red, Bg: &blue, TextAttributes: attrs}, ColorModeTruecolorN)
		if got != e[1].(string) {
			t.Errorf("style[%d] = %q, want %q", i, got, e[1].(string))
		}
	}
	var withAnsi []string
	loadGoldenSection(t, "styleWithAnsi", &withAnsi)
	for i, want := range withAnsi {
		var attrs TextAttributes
		switch i {
		case 1:
			attrs.Bold = true
		case 2:
			attrs.Dim = true
		case 3:
			attrs.Italic = true
		case 4:
			attrs.Underline = true
		case 5:
			attrs.Inverse = true
		case 6:
			attrs.Strikethrough = true
		case 7:
			attrs.Bold, attrs.Italic, attrs.Underline = true, true, true
		}
		got := StyleTextWithAnsi("y", "\x1b[38;2;1;2;3m", "\x1b[48;2;9;8;7m", attrs)
		if got != want {
			t.Errorf("styleWithAnsi[%d] = %q, want %q", i, got, want)
		}
	}
}

func TestColorsGoldenOscReplies(t *testing.T) {
	var entries []([]any)
	loadGoldenSection(t, "osc", &entries)
	for i, e := range entries {
		data := e[0].(string)
		reply := e[1].(map[string]any)
		target, rgb, ok := ParseOscColorResponse(data)
		present, _ := reply["target"].(bool)
		_ = present
		if reply["target"] == nil {
			if ok {
				t.Errorf("osc[%d]: parse succeeded, want failure", i)
			}
			continue
		}
		if !ok {
			t.Errorf("osc[%d]: parse failed, want success", i)
			continue
		}
		switch wantTarget := reply["target"].(type) {
		case string:
			switch wantTarget {
			case "foreground":
				if !target.Foreground || target.PaletteIndex >= 0 {
					t.Errorf("osc[%d]: target = %+v, want foreground", i, target)
				}
			case "background":
				if target.Foreground || target.PaletteIndex >= 0 {
					t.Errorf("osc[%d]: target = %+v, want background", i, target)
				}
			}
		case float64:
			if target.PaletteIndex != int(wantTarget) {
				t.Errorf("osc[%d]: target = %+v, want palette %d", i, target, int(wantTarget))
			}
		}
		if reply["rgb"] == nil {
			if rgb != nil {
				t.Errorf("osc[%d]: rgb = %+v, want nil", i, rgb)
			}
		} else {
			want := decodeGoldenRgb(t, reply["rgb"])
			if rgb == nil || *rgb != want.value() {
				t.Errorf("osc[%d]: rgb = %+v, want %+v", i, rgb, want.value())
			}
		}
	}
}

func TestColorsGoldenSchemeReports(t *testing.T) {
	var entries []string
	loadGoldenSection(t, "scheme", &entries)
	inputs := []string{"\x1b[?997;1n", "\x1b[?997;2n", "\x1b[?997;2n\x1b[?997;2n"}
	for i, want := range entries {
		scheme, ok := ParseTerminalColorSchemeReport(inputs[i])
		if !ok || scheme != want {
			t.Errorf("scheme[%d] = %q ok=%v, want %q", i, scheme, ok, want)
		}
	}
}

// ============================================================================
// Golden decoding helpers (JSON numbers → the shapes the sections carry)
// ============================================================================

func loadGoldenSection(t *testing.T, name string, target any) {
	t.Helper()
	golden := loadColorsGolden(t)
	raw, ok := golden[name]
	if !ok {
		t.Fatalf("golden section %q missing", name)
	}
	if err := json.Unmarshal(raw, target); err != nil {
		t.Fatalf("decode golden section %q: %v", name, err)
	}
}

func decodeGoldenTriple(t *testing.T, v any) [3]float64 {
	t.Helper()
	arr, ok := v.([]any)
	if !ok || len(arr) != 3 {
		t.Fatalf("expected [r,g,b] triple, got %#v", v)
	}
	var out [3]float64
	for i, x := range arr {
		out[i] = x.(float64)
	}
	return out
}

func decodeGoldenRgb(t *testing.T, v any) goldenRgb {
	t.Helper()
	m, ok := v.(map[string]any)
	if !ok {
		t.Fatalf("expected rgb object, got %#v", v)
	}
	return goldenRgb{R: int(m["r"].(float64)), G: int(m["g"].(float64)), B: int(m["b"].(float64))}
}

func decodeGoldenOkhsl(t *testing.T, v any) goldenOkhsl {
	t.Helper()
	m, ok := v.(map[string]any)
	if !ok {
		t.Fatalf("expected okhsl object, got %#v", v)
	}
	return goldenOkhsl{H: m["h"].(float64), S: m["s"].(float64), L: m["l"].(float64)}
}

func decodeGoldenOklch(t *testing.T, v any) goldenOklch {
	t.Helper()
	m, ok := v.(map[string]any)
	if !ok {
		t.Fatalf("expected oklch object, got %#v", v)
	}
	return goldenOklch{L: m["l"].(float64), C: m["c"].(float64), H: m["h"].(float64)}
}

func decodeGoldenHexPair(t *testing.T, v any) string {
	t.Helper()
	s, ok := v.(string)
	if !ok {
		t.Fatalf("expected hex string, got %#v", v)
	}
	return s
}

func decodeGoldenAttrs(t *testing.T, v any) TextAttributes {
	t.Helper()
	m, ok := v.(map[string]any)
	if !ok {
		t.Fatalf("expected attrs object, got %#v", v)
	}
	b := func(key string) bool { val, _ := m[key].(bool); return val }
	return TextAttributes{
		Bold: b("bold"), Dim: b("dim"), Italic: b("italic"),
		Underline: b("underline"), Inverse: b("inverse"), Strikethrough: b("strikethrough"),
	}
}
